/// <summary>
/// extends SysOperationServiceController
/// </summary>
internal final class AVACRLLimitExpiredController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    AVACRLLimitExpiredController controller;

    controller = new AVACRLLimitExpiredController(classStr(AVACRLLimitExpiredService),
                                       methodStr(AVACRLLimitExpiredService, startOperation),
                                       SysOperationExecutionMode::Synchronous);

    controller.startOperation();
}

/// <summary>
/// Returns default classDescription
/// </summary>
/// <returns>ClassDescription</returns>
protected ClassDescription defaultCaption()
{
    return "@NDX:NXACRLExpired";
}
